-- -----------------------------------------------------------------------------
-- 2. CATEGORY
-- The three emission domains used by EcoTrack activity logs.
-- -----------------------------------------------------------------------------
INSERT INTO CATEGORY (category_name, description) VALUES
('Transportation', 'Travel by road, rail or air, including private vehicles and public transport.'),
('Food',           'Dietary consumption converted to CO2e using food-type emission factors.'),
('Electricity',    'Household or rooftop electricity use converted using grid or solar factors.');

SET @cat_transport   = (SELECT category_id FROM CATEGORY WHERE category_name = 'Transportation');
SET @cat_food        = (SELECT category_id FROM CATEGORY WHERE category_name = 'Food');
SET @cat_electricity = (SELECT category_id FROM CATEGORY WHERE category_name = 'Electricity');

