(@cat_transport,   'City diesel bus',           0.089000, 'kg CO2e/km',  'Municipal / STU bus, per passenger-km at moderate occupancy.'),
(@cat_transport,   'Metro rail',                0.028000, 'kg CO2e/km',  'Urban metro (Delhi/Bengaluru/Mumbai), per passenger-km.'),
(@cat_transport,   'Suburban local train',      0.032000, 'kg CO2e/km',  'Mumbai/Chennai-style EMU local, per passenger-km.'),
